  1→package cli
  2→
  3→import (
  4→	"context"
  5→	"errors"
  6→	"fmt"
  7→	"io"
  8→	"log/slog"
  9→	"os"
 10→	"path/filepath"
 11→	"sort"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/agent"
 14→	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
 15→	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
 16→	"github.com/entireio/cli/cmd/entire/cli/logging"
 17→	"github.com/entireio/cli/cmd/entire/cli/paths"
 18→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 19→	"github.com/entireio/cli/cmd/entire/cli/trailers"
 20→
 21→	"github.com/charmbracelet/huh"
 22→	"github.com/go-git/go-git/v6"
 23→	"github.com/go-git/go-git/v6/plumbing"
 24→	"github.com/go-git/go-git/v6/plumbing/object"
 25→	"github.com/spf13/cobra"
 26→)
 27→
 28→func newResumeCmd() *cobra.Command {
 29→	var force bool
 30→
 31→	cmd := &cobra.Command{
 32→		Use:   "resume <branch>",
 33→		Short: "Switch to a branch and resume its session",
 34→		Long: `Switch to a local branch and resume the agent session from its last commit.
 35→
 36→This command:
 37→1. Checks out the specified branch
 38→2. Finds the session ID from commits unique to this branch (not on main)
 39→3. Restores the session log if it doesn't exist locally
 40→4. Shows the command to resume the session
 41→
 42→If the branch doesn't exist locally but exists on origin, you'll be prompted
 43→to fetch it.
 44→
 45→If newer commits without checkpoints exist on the branch (e.g., after merging main
 46→or cherry-picking from elsewhere), this operation will reset your Git status to the
 47→most recent commit with a checkpoint.  You'll be prompted to confirm resuming in this case.`,
 48→		Args: cobra.ExactArgs(1),
 49→		RunE: func(cmd *cobra.Command, args []string) error {
 50→			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
 51→				return nil
 52→			}
 53→			return runResume(cmd.Context(), cmd, args[0], force)
 54→		},
 55→	}
 56→
 57→	cmd.Flags().BoolVarP(&force, "force", "f", false, "Resume from older checkpoint without confirmation")
 58→
 59→	return cmd
 60→}
 61→
 62→func runResume(ctx context.Context, cmd *cobra.Command, branchName string, force bool) error {
 63→	w := cmd.OutOrStdout()
 64→	errW := cmd.ErrOrStderr()
 65→
 66→	// Check if we're already on this branch
 67→	currentBranch, err := GetCurrentBranch(ctx)
 68→	if err == nil && currentBranch == branchName {
 69→		// Already on the branch, skip checkout
 70→		return resumeFromCurrentBranch(ctx, w, errW, branchName, force)
 71→	}
 72→
 73→	// Check if branch exists locally
 74→	exists, err := BranchExistsLocally(ctx, branchName)
 75→	if err != nil {
 76→		return fmt.Errorf("failed to check branch: %w", err)
 77→	}
 78→
 79→	if !exists {
 80→		// Branch doesn't exist locally, check if it exists on remote
 81→		remoteExists, err := BranchExistsOnRemote(ctx, branchName)
 82→		if err != nil {
 83→			return fmt.Errorf("failed to check remote branch: %w", err)
 84→		}
 85→
 86→		if !remoteExists {
 87→			return fmt.Errorf("branch '%s' not found locally or on origin", branchName)
 88→		}
 89→
 90→		// Ask user if they want to fetch from remote
 91→		shouldFetch, err := promptFetchFromRemote(branchName)
 92→		if err != nil {
 93→			return err
 94→		}
 95→		if !shouldFetch {
 96→			return nil
 97→		}
 98→
 99→		// Fetch and checkout the remote branch
100→		fmt.Fprintf(w, "Fetching branch '%s' from origin...\n", branchName)
101→		if err := FetchAndCheckoutRemoteBranch(ctx, branchName); err != nil {
102→			fmt.Fprintf(errW, "Error: failed to checkout branch: %v\n", err)
103→			return NewSilentError(errors.New("failed to checkout branch"))
104→		}
105→		fmt.Fprintf(w, "✓ Switched to branch %s\n", branchName)
106→	} else {
107→		// Branch exists locally, check for uncommitted changes before checkout
108→		hasChanges, err := HasUncommittedChanges(ctx)
109→		if err != nil {
110→			return fmt.Errorf("failed to check for uncommitted changes: %w", err)
111→		}
112→		if hasChanges {
113→			return errors.New("you have uncommitted changes. Please commit or stash them first")
114→		}
115→
116→		// Checkout the branch
117→		if err := CheckoutBranch(ctx, branchName); err != nil {
118→			fmt.Fprintf(errW, "Error: failed to checkout branch: %v\n", err)
119→			return NewSilentError(errors.New("failed to checkout branch"))
120→		}
121→		fmt.Fprintf(w, "✓ Switched to branch %s\n", branchName)
122→	}
123→
124→	return resumeFromCurrentBranch(ctx, w, errW, branchName, force)
125→}
126→
127→func resumeFromCurrentBranch(ctx context.Context, w, errW io.Writer, branchName string, force bool) error {
128→	repo, err := openRepository(ctx)
129→	if err != nil {
130→		return fmt.Errorf("not a git repository: %w", err)
131→	}
132→
133→	// Find a commit with an Entire-Checkpoint trailer, looking at branch-only commits
134→	result, err := findBranchCheckpoints(repo, branchName)
135→	if err != nil {
136→		return err
137→	}
138→	if len(result.checkpointIDs) == 0 {
139→		fmt.Fprintf(w, "No Entire checkpoint found on branch '%s'\n", branchName)
140→		return nil
141→	}
142→
143→	// If there are newer commits without checkpoints, ask for confirmation.
144→	// Merge commits (e.g., from merging main) don't count as "work" and are skipped silently.
145→	if result.newerCommitsExist && !force {
146→		fmt.Fprintf(w, "Found checkpoint in an older commit.\n")
147→		fmt.Fprintf(w, "There are %d newer commit(s) on this branch without checkpoints.\n", result.newerCommitCount)
148→		fmt.Fprintf(w, "Checkpoint from: %s %s\n\n", result.commitHash[:7], firstLine(result.commitMessage))
149→
150→		shouldResume, err := promptResumeFromOlderCheckpoint()
151→		if err != nil {
152→			return err
153→		}
154→		if !shouldResume {
155→			fmt.Fprintf(w, "Resume cancelled.\n")
156→			return nil
157→		}
158→	}
159→
160→	checkpointID := result.checkpointIDs[0]
161→
162→	// Multiple checkpoints (squash merge): resolve latest by CreatedAt timestamp.
163→	// resolveLatestCheckpoint also returns the metadata tree so we can reuse it
164→	// for the ReadCheckpointMetadata call below without a redundant lookup.
165→	var metadataTree *object.Tree
166→	if len(result.checkpointIDs) > 1 {
167→		latest, tree, err := resolveLatestCheckpoint(ctx, repo, result.checkpointIDs)
168→		if err != nil {
169→			// No metadata available — nothing to resume from
170→			fmt.Fprintf(w, "Found %d checkpoints for commit %s but metadata is not available\n",
171→				len(result.checkpointIDs), result.commitHash[:7])
172→			return checkRemoteMetadata(ctx, w, errW, repo, result.checkpointIDs[0])
173→		}
174→		skipped := len(result.checkpointIDs) - 1
175→		fmt.Fprintf(w, "Found %d checkpoints for commit %s, resuming from the latest (%d older checkpoints skipped)\n",
176→			len(result.checkpointIDs), result.commitHash[:7], skipped)
177→		checkpointID = latest
178→		metadataTree = tree
179→	}
180→
181→	// Get metadata branch tree for lookups (reuse from resolveLatestCheckpoint if available)
182→	if metadataTree == nil {
183→		var err error
184→		metadataTree, err = getMetadataTree(ctx, repo)
185→		if err != nil {
186→			// No local metadata branch, check if remote has it
187→			return checkRemoteMetadata(ctx, w, errW, repo, checkpointID)
188→		}
189→	}
190→
191→	// Look up metadata from sharded path
192→	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
193→	if err != nil {
194→		// Checkpoint exists in commit but no local metadata - check remote
195→		return checkRemoteMetadata(ctx, w, errW, repo, checkpointID)
196→	}
197→
198→	return resumeSession(ctx, w, errW, metadata, force)
199→}
200→
201→// resolveLatestCheckpoint reads metadata for each checkpoint ID and returns
202→// the one with the latest CreatedAt, along with the metadata tree for reuse.
203→// It tries the local metadata branch first, then fetches from remote, then
204→// falls back to the remote tree directly.
205→func resolveLatestCheckpoint(ctx context.Context, repo *git.Repository, checkpointIDs []id.CheckpointID) (id.CheckpointID, *object.Tree, error) {
206→	metadataTree, err := getMetadataTree(ctx, repo)
207→	if err != nil {
208→		return id.EmptyCheckpointID, nil, err
209→	}
210→	infoMap := make(map[id.CheckpointID]strategy.CheckpointInfo, len(checkpointIDs))
211→	for _, cpID := range checkpointIDs {
212→		metadata, err := strategy.ReadCheckpointMetadata(metadataTree, cpID.Path())
213→		if err != nil {
214→			continue
215→		}
216→		infoMap[cpID] = *metadata
217→	}
218→	latest, found := strategy.ResolveLatestCheckpointFromMap(checkpointIDs, infoMap)
219→	if !found {
220→		return id.EmptyCheckpointID, nil, errors.New("no checkpoint metadata found")
221→	}
222→	return latest.CheckpointID, metadataTree, nil
223→}
224→
225→// getMetadataTree returns the metadata branch tree, trying a treeless fetch
226→// first to ensure local data is up-to-date, then falling back to local,
227→// then full fetch, then remote tree directly.
228→func getMetadataTree(ctx context.Context, repo *git.Repository) (*object.Tree, error) {
229→	// Always try treeless fetch first to ensure local branch is up-to-date
230→	if fetchErr := FetchMetadataTreeOnly(ctx); fetchErr == nil {
231→		metadataTree, err := strategy.GetMetadataBranchTree(repo)
232→		if err == nil {
233→			return metadataTree, nil
234→		}
235→	}
236→
237→	// Try local (may have been set by a prior fetch or push)
238→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
239→	if err == nil {
240→		return metadataTree, nil
241→	}
242→
243→	// Fallback: full fetch from remote
244→	if fetchErr := FetchMetadataBranch(ctx); fetchErr == nil {
245→		metadataTree, err = strategy.GetMetadataBranchTree(repo)
246→		if err == nil {
247→			return metadataTree, nil
248→		}
249→	}
250→
251→	// Try remote tree directly
252→	remoteTree, remoteErr := strategy.GetRemoteMetadataBranchTree(repo)
253→	if remoteErr != nil {
254→		return nil, fmt.Errorf("metadata branch not available: %w", remoteErr)
255→	}
256→	return remoteTree, nil
257→}
258→
259→// ensureTranscriptBlobs checks which transcript blobs for a checkpoint are
260→// present in the local object store (via go-git) and fetches any missing
261→// ones from the remote (via git CLI).
262→// This enables the treeless-fetch optimization: tree objects are fetched first,
263→// then only the specific full.jsonl blobs needed for resume are downloaded.
264→func ensureTranscriptBlobs(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
265→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
266→	if err != nil {
267→		// If we can't get the tree, blobs can't be checked — caller will handle the error
268→		return nil //nolint:nilerr // Tree unavailable means no sparse fetch possible
269→	}
270→
271→	refs, err := checkpoint.CollectTranscriptBlobHashes(metadataTree, checkpointID)
272→	if err != nil {
273→		// Tree navigation failed — not fatal, ReadSessionContent will fail with a clear error
274→		return nil //nolint:nilerr // Best-effort blob prefetch
275→	}
276→
277→	resolver := checkpoint.NewBlobResolver(repo.Storer)
278→	var missing []plumbing.Hash
279→	for _, ref := range refs {
280→		if !resolver.HasBlob(ref.Hash) {
281→			missing = append(missing, ref.Hash)
282→		}
283→	}
284→	if len(missing) == 0 {
285→		return nil
286→	}
287→
288→	return FetchBlobsByHash(ctx, missing)
289→}
290→
291→// branchCheckpointsResult contains the result of searching for checkpoints on a branch.
292→type branchCheckpointsResult struct {
293→	checkpointIDs     []id.CheckpointID
294→	commitHash        string
295→	commitMessage     string
296→	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
297→	newerCommitCount  int  // count of branch-only commits without checkpoints
298→}
299→
300→// findBranchCheckpoints finds the most recent commit with an Entire-Checkpoint trailer
301→// among commits that are unique to this branch (not reachable from the default branch).
302→// This handles the case where main has been merged into the feature branch.
303→func findBranchCheckpoints(repo *git.Repository, branchName string) (*branchCheckpointsResult, error) {
304→	result := &branchCheckpointsResult{}
305→
306→	// Get HEAD commit
307→	head, err := repo.Head()
308→	if err != nil {
309→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
310→	}
311→
312→	headCommit, err := repo.CommitObject(head.Hash())
313→	if err != nil {
314→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
315→	}
316→
317→	// First, check if HEAD itself has a checkpoint (most common case)
318→	if cpIDs := trailers.ParseAllCheckpoints(headCommit.Message); len(cpIDs) > 0 {
319→		result.checkpointIDs = cpIDs
320→		result.commitHash = head.Hash().String()
321→		result.commitMessage = headCommit.Message
322→		result.newerCommitsExist = false
323→		return result, nil
324→	}
325→
326→	// HEAD doesn't have a checkpoint - find branch-only commits
327→	// Get the default branch name
328→	defaultBranch := getDefaultBranchFromRemote(repo)
329→	if defaultBranch == "" {
330→		// Fallback: try common names
331→		for _, name := range []string{"main", "master"} {
332→			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
333→				defaultBranch = name
334→				break
335→			}
336→		}
337→	}
338→
339→	// If we can't find a default branch, or we're on it, just walk all commits
340→	if defaultBranch == "" || defaultBranch == branchName {
341→		return findCheckpointInHistory(headCommit, nil), nil
342→	}
343→
344→	// Get the default branch reference
345→	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
346→	if err != nil {
347→		// Default branch doesn't exist locally, fall back to walking all commits
348→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
349→	}
350→
351→	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
352→	if err != nil {
353→		// Can't get default commit, fall back to walking all commits
354→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
355→	}
356→
357→	// Find merge base
358→	mergeBase, err := headCommit.MergeBase(defaultCommit)
359→	if err != nil || len(mergeBase) == 0 {
360→		// No common ancestor, fall back to walking all commits
361→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
362→	}
363→
364→	// Walk from HEAD to merge base, looking for checkpoint
365→	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
366→}
367→
368→// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
369→// If stopAt is provided, stops when reaching that commit (exclusive).
370→// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
371→// It distinguishes between merge commits (bringing in other branches) and regular commits
372→// (actual branch work) to avoid false warnings after merging main.
373→func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointsResult {
374→	result := &branchCheckpointsResult{}
375→	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
376→	const maxCommits = 100 // Limit search depth
377→	totalChecked := 0
378→
379→	current := start
380→	for current != nil && totalChecked < maxCommits {
381→		// Stop if we've reached the boundary
382→		if stopAt != nil && current.Hash == *stopAt {
383→			break
384→		}
385→
386→		// Check for checkpoint trailer
387→		if cpIDs := trailers.ParseAllCheckpoints(current.Message); len(cpIDs) > 0 {
388→			result.checkpointIDs = cpIDs
389→			result.commitHash = current.Hash.String()
390→			result.commitMessage = current.Message
391→			// Only warn about branch work commits, not merge commits
392→			result.newerCommitsExist = branchWorkCommits > 0
393→			result.newerCommitCount = branchWorkCommits
394→			return result
395→		}
396→
397→		// Only count regular commits (not merge commits) as "branch work"
398→		if current.NumParents() <= 1 {
399→			branchWorkCommits++
400→		}
401→
402→		totalChecked++
403→
404→		// Move to parent (first parent for merge commits - follows the main line)
405→		if current.NumParents() == 0 {
406→			break
407→		}
408→		parent, err := current.Parent(0)
409→		if err != nil {
410→			// Can't get parent, treat as end of history
411→			break
412→		}
413→		current = parent
414→	}
415→
416→	// No checkpoint found
417→	return result
418→}
419→
420→// promptResumeFromOlderCheckpoint asks the user if they want to resume from an older checkpoint.
421→func promptResumeFromOlderCheckpoint() (bool, error) {
422→	var confirmed bool
423→
424→	form := NewAccessibleForm(
425→		huh.NewGroup(
426→			huh.NewConfirm().
427→				Title("Resume from this older checkpoint?").
428→				Value(&confirmed),
429→		),
430→	)
431→
432→	if err := form.Run(); err != nil {
433→		if errors.Is(err, huh.ErrUserAborted) {
434→			return false, nil
435→		}
436→		return false, fmt.Errorf("failed to get confirmation: %w", err)
437→	}
438→
439→	return confirmed, nil
440→}
441→
442→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
443→// and automatically fetches it if available.
444→func checkRemoteMetadata(ctx context.Context, w, errW io.Writer, repo *git.Repository, checkpointID id.CheckpointID) error {
445→	// Try to get remote metadata branch tree
446→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
447→	if err != nil {
448→		fmt.Fprintf(w, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
449→		fmt.Fprintf(w, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
450→		return nil //nolint:nilerr // Informational message, not a fatal error
451→	}
452→
453→	// Check if the checkpoint exists on the remote
454→	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
455→	if err != nil {
456→		fmt.Fprintf(w, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
457→		return nil //nolint:nilerr // Informational message, not a fatal error
458→	}
459→
460→	// Metadata exists on remote but not locally - fetch it automatically
461→	fmt.Fprintf(w, "Fetching session metadata from origin...\n")
462→	if err := FetchMetadataBranch(ctx); err != nil {
463→		fmt.Fprintf(errW, "Error: failed to fetch metadata: %v\n", err)
464→		fmt.Fprintf(errW, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
465→		return NewSilentError(errors.New("failed to fetch metadata"))
466→	}
467→
468→	// Now resume the session with the fetched metadata
469→	return resumeSession(ctx, w, errW, metadata, false)
470→}
471→
472→// resumeSession restores and displays the resume command for a specific session.
473→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
474→// If force is false, prompts for confirmation when local logs have newer timestamps.
475→// The caller must provide the already-resolved checkpoint metadata to avoid redundant lookups
476→// and to support both local and remote metadata trees.
477→func resumeSession(ctx context.Context, w, errW io.Writer, metadata *strategy.CheckpointInfo, force bool) error {
478→	checkpointID := metadata.CheckpointID
479→	sessionID := metadata.SessionID
480→
481→	// Resolve agent from checkpoint metadata (same as rewind)
482→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
483→	if err != nil {
484→		return fmt.Errorf("failed to resolve agent: %w", err)
485→	}
486→
487→	// Initialize logging context with agent
488→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
489→
490→	logging.Debug(logCtx, "resume session started",
491→		slog.String("checkpoint_id", checkpointID.String()),
492→		slog.String("session_id", sessionID),
493→	)
494→
495→	// Get worktree root for session directory lookup
496→	repoRoot, err := paths.WorktreeRoot(ctx)
497→	if err != nil {
498→		return fmt.Errorf("failed to get worktree root: %w", err)
499→	}
500→
501→	sessionDir, err := ag.GetSessionDir(repoRoot)
502→	if err != nil {
503→		return fmt.Errorf("failed to determine session directory: %w", err)
504→	}
505→
506→	// Create directory if it doesn't exist
507→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
508→		return fmt.Errorf("failed to create session directory: %w", err)
509→	}
510→
511→	// Get strategy and restore sessions using full checkpoint data
512→	strat := GetStrategy(ctx)
513→
514→	// Ensure transcript blobs are available locally before RestoreLogsOnly reads them.
515→	// After a treeless fetch, tree objects are present but full.jsonl blobs may not be.
516→	// This fetches only the specific blobs needed for this checkpoint.
517→	repo, repoErr := openRepository(ctx)
518→	if repoErr == nil {
519→		if blobErr := ensureTranscriptBlobs(ctx, repo, checkpointID); blobErr != nil {
520→			logging.Warn(logCtx, "failed to ensure transcript blobs, restore may fail",
521→				slog.String("error", blobErr.Error()),
522→			)
523→		}
524→	}
525→
526→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
527→	// Create a logs-only rewind point with Agent populated (same as rewind)
528→	point := strategy.RewindPoint{
529→		IsLogsOnly:   true,
530→		CheckpointID: checkpointID,
531→		Agent:        metadata.Agent,
532→	}
533→
534→	sessions, restoreErr := strat.RestoreLogsOnly(ctx, w, errW, point, force)
535→	if restoreErr != nil || len(sessions) == 0 {
536→		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
537→		return resumeSingleSession(ctx, w, errW, ag, sessionID, checkpointID, repoRoot, force)
538→	}
539→
540→	logging.Debug(logCtx, "resume session completed",
541→		slog.String("checkpoint_id", checkpointID.String()),
542→		slog.Int("session_count", len(sessions)),
543→	)
544→
545→	return displayRestoredSessions(w, sessions)
546→}
547→
548→// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
549→func displayRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
550→	sort.SliceStable(sessions, func(i, j int) bool {
551→		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
552→	})
553→
554→	if len(sessions) > 1 {
555→		fmt.Fprintf(w, "\n✓ Restored %d sessions. To continue, run:\n", len(sessions))
556→	} else if len(sessions) == 1 {
557→		fmt.Fprintf(w, "✓ Restored session %s.\n", sessions[0].SessionID)
558→		fmt.Fprintf(w, "\nTo continue this session, run:\n")
559→	}
560→
561→	isMulti := len(sessions) > 1
562→	for i, sess := range sessions {
563→		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
564→		if err != nil {
565→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
566→		}
567→		printSessionCommand(w, sessionAgent.FormatResumeCommand(sess.SessionID), sess.Prompt, isMulti, i == len(sessions)-1)
568→	}
569→
570→	return nil
571→}
572→
573→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
574→// Always overwrites existing session logs to ensure consistency with checkpoint state.
575→// If force is false, prompts for confirmation when local log has newer timestamps.
576→func resumeSingleSession(ctx context.Context, w, errW io.Writer, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
577→	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
578→	if err != nil {
579→		return fmt.Errorf("failed to resolve transcript path: %w", err)
580→	}
581→
582→	if checkpointID.IsEmpty() {
583→		logging.Debug(ctx, "resume session: empty checkpoint ID",
584→			slog.String("checkpoint_id", checkpointID.String()),
585→		)
586→		fmt.Fprintf(w, "Session '%s' found in commit trailer but session log not available\n", sessionID)
587→		fmt.Fprintf(w, "\nTo continue this session, run:\n")
588→		fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
589→		return nil
590→	}
591→
592→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
593→	if err != nil {
594→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
595→			logging.Debug(ctx, "resume session completed (no metadata)",
596→				slog.String("checkpoint_id", checkpointID.String()),
597→				slog.String("session_id", sessionID),
598→			)
599→			fmt.Fprintf(w, "Session '%s' found in commit trailer but session log not available\n", sessionID)
600→			fmt.Fprintf(w, "\nTo continue this session, run:\n")
601→			fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
602→			return nil
603→		}
604→		logging.Error(ctx, "resume session failed",
605→			slog.String("checkpoint_id", checkpointID.String()),
606→			slog.String("session_id", sessionID),
607→			slog.String("error", err.Error()),
608→		)
609→		return fmt.Errorf("failed to get session log: %w", err)
610→	}
611→
612→	// Check if local file has newer timestamps than checkpoint
613→	if !force {
614→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
615→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
616→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
617→
618→		if status == strategy.StatusLocalNewer {
619→			sessions := []strategy.SessionRestoreInfo{{
620→				SessionID:      sessionID,
621→				Status:         status,
622→				LocalTime:      localTime,
623→				CheckpointTime: checkpointTime,
624→			}}
625→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(errW, sessions)
626→			if promptErr != nil {
627→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
628→			}
629→			if !shouldOverwrite {
630→				fmt.Fprintf(w, "Resume cancelled. Local session log preserved.\n")
631→				return nil
632→			}
633→		}
634→	}
635→
636→	// Ensure parent directory exists
637→	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
638→		return fmt.Errorf("failed to create session directory: %w", err)
639→	}
640→
641→	agentSession := &agent.AgentSession{
642→		SessionID:  sessionID,
643→		AgentName:  ag.Name(),
644→		RepoPath:   repoRoot,
645→		SessionRef: sessionLogPath,
646→		NativeData: logContent,
647→	}
648→
649→	// Write the session using the agent's WriteSession method
650→	if err := ag.WriteSession(ctx, agentSession); err != nil {
651→		logging.Error(ctx, "resume session failed during write",
652→			slog.String("checkpoint_id", checkpointID.String()),
653→			slog.String("session_id", sessionID),
654→			slog.String("error", err.Error()),
655→		)
656→		return fmt.Errorf("failed to write session: %w", err)
657→	}
658→
659→	logging.Debug(ctx, "resume session completed",
660→		slog.String("checkpoint_id", checkpointID.String()),
661→		slog.String("session_id", sessionID),
662→	)
663→
664→	fmt.Fprintf(w, "✓ Session restored to: %s\n", sessionLogPath)
665→	fmt.Fprintf(w, "  Session: %s\n", sessionID)
666→	fmt.Fprintf(w, "\nTo continue this session, run:\n")
667→	fmt.Fprintf(w, "  %s\n", ag.FormatResumeCommand(sessionID))
668→
669→	return nil
670→}
671→
672→func promptFetchFromRemote(branchName string) (bool, error) {
673→	var confirmed bool
674→
675→	form := NewAccessibleForm(
676→		huh.NewGroup(
677→			huh.NewConfirm().
678→				Title(fmt.Sprintf("Branch '%s' not found locally. Fetch from origin?", branchName)).
679→				Value(&confirmed),
680→		),
681→	)
682→
683→	if err := form.Run(); err != nil {
684→		if errors.Is(err, huh.ErrUserAborted) {
685→			return false, nil
686→		}
687→		return false, fmt.Errorf("failed to get confirmation: %w", err)
688→	}
689→
690→	return confirmed, nil
691→}
692→
693→// firstLine returns the first line of a string
694→func firstLine(s string) string {
695→	for i, c := range s {
696→		if c == '\n' {
697→			return s[:i]
698→		}
699→	}
700→	return s
701→}
