	wantCommand := "  " + ag.FormatResumeCommand(session.SessionID) + "  # Implement auth\n"
	if !strings.Contains(got, wantCommand) {
		t.Fatalf("displayRestoredSessions() missing command %q in %q", wantCommand, got)
	}
}

